#include <iostream>

class Counter {
public:
    Counter& add(int n) {
        value += n;
        return *this;
    }
    int get() const { return value; }
private:
    int value = 0;
};

int main() {
    Counter c;
    c.add(2).add(3);
    std::cout << c.get() << "\n";
    return 0;
}

