#include <iostream>

class Range {
public:
    Range() : Range(0, 10) {}
    Range(int lo, int hi) : low(lo), high(hi) {}
    int span() const { return high - low; }
private:
    int low;
    int high;
};

int main() {
    Range r;
    std::cout << r.span() << "\n";
    return 0;
}

